lv_font_t *sim_font_cjk_style(int px, bool italic)
{
    if (px < 6) {
        px = 6;
    }
    for (int i = 0; i < s_cache_n; i++) {
        if (s_cache[i].px == px && s_cache[i].italic == italic) {
            return s_cache[i].font;
        }
    }

    lv_font_t *font = lv_freetype_font_create(cjk_font_path(),
                                              LV_FREETYPE_FONT_RENDER_MODE_BITMAP,
                                              (uint32_t)px,
                                              italic ? LV_FREETYPE_FONT_STYLE_ITALIC
                                                     : LV_FREETYPE_FONT_STYLE_NORMAL);
    if (!font) {
        fprintf(stderr, "sim: cannot load CJK font %s, using built-in subset\n",
                cjk_font_path());
        font = (lv_font_t *)&lv_font_source_han_sans_sc_16_cjk;
    }

    if (s_cache_n < SIM_FONT_CACHE) {
        s_cache[s_cache_n].px = px;
        s_cache[s_cache_n].italic = italic;
        s_cache[s_cache_n].font = font;
        s_cache_n++;
    }
    return font;
}

lv_font_t *sim_font_cjk(int px)
{
    return sim_font_cjk_style(px, false);
}
